import{z as i,x as d,o,c as A,q as r,j as t,D as e,d as E,s as l,S as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"fork","description":"","frontmatter":{"title":"fork","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fork.md","filePath":"cs/fork.md","lastUpdated":1791063341000}'),c={name:"cs/fork.md"};function p(B,a,f,D,h,m){const s=d("Mermaid");return o(),A("div",null,[a[2]||(a[2]=r('<h1 id="fork" tabindex="-1">fork <a class="header-anchor" href="#fork" aria-label="Permalink to &quot;fork&quot;">​</a></h1><div class="epigraph"><p>fork 把当前进程复制成子进程：子返回 0，父返回子的 PID；其后二者独立调度，默认共享打开文件表的引用。</p><footer>—— 据 Tanenbaum and Bos, Modern Operating Systems；Ritchie and Thompson, The UNIX Time-Sharing System 整理</footer></div><p><a href="/cs/pcb-task-struct">上一课</a>给出可分配的 PCB。用户要再跑一份程序，不能自己写一块内核对象。<a href="/cs/syscall-abi">系统调用 ABI</a> 已有陷入约定。缺口是 Unix 的创建原语：<strong>fork</strong>——复制当前映像，一次调用两个返回。本课不把写时复制的页表细节写完，那是更后的 <a href="/cs/cow-fork">cow-fork</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若只有「从文件加载新进程」，交互式 shell 无法在保留打开终端的同时换掉地址空间。fork 先克隆：子继承寄存器（除返回值）、页表（逻辑副本）、文件描述符。父继续原来的流。缺口不是新的 PCB 字段清单，而是这一调用的语义：谁返回什么、哪些资源共享引用计数、哪些必须真复制。</p><p><span class="marginnote">直觉类比：fork 像按下了「复印自己」的按钮——按下的人突然变成两个，一个拿着原件继续原来的工作（父进程），一个拿着复印件从同一个位置接着走（子进程）。唯一的区别是口袋里的纸条：父拿到子的编号，子拿到 0。</span></p><p><span class="marginnote">子进程地址空间在逻辑上独立：子写自己的栈不应改父的栈。实现上先共享只读页再在写时拆，是 cow 课；本课语义当立即独立。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>系统调用：分配新 PCB 与新 PID，复制或共享内存描述符、文件表（引用 +1）、信号掩码。子的 trapframe 从父拷来，把返回值槽写成 0；父的返回值是子 PID。子被放进就绪队列。失败则父得到错误，不存在「半个进程」。</p>',9)),(o(),t(n,null,{default:e(()=>[l(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%88%B6%20PCB%22%5D%20--%3E%20F%5B%22fork%22%5D%0A%20%20F%20--%3E%20P2%5B%22%E7%88%B6%3A%20%E8%BF%94%E5%9B%9E%E5%AD%90%20PID%22%5D%0A%20%20F%20--%3E%20C%5B%22%E5%AD%90%20PCB%3A%20%E8%BF%94%E5%9B%9E%200%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p>多线程进程里 fork 只复制调用线程，POSIX 有规定；主干承认这一点，不背手册全文。内核线程一般不对外 fork。</p><p><span class="marginnote">常见误区：初学者以为 fork 之后父进程一定先跑。实际上 fork 只是把子放进就绪队列，之后谁被调度全由内核决定——可能父先、可能子先、也可能每次开机都不一样。所以 <code>if (pid == 0)</code> 的两个分支都必须写得独立正确，不能赌执行顺序。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>fork 把「创建」从「加载程序」拆开：先有两份映像，再用下一课 <code>execve</code> 把其中一份换成新程序。shell 的典型路径正是 fork 后子 exec、父 wait。返回值约定让同一份用户代码用 <code>if</code> 分成两路，不必两套入口。</p><p>复制页表根但不复制全部物理页，是性能；语义仍是独立地址空间。<a href="/cs/paging-vm">分页</a> 的权限位稍后在 cow 课改写。</p><p><span class="marginnote">为什么把「复制」和「换程序」拆成两步如此重要：fork 与 execve 之间有一个窗口，子进程可以在换身之前先改自己的文件描述符——比如把标准输出指到一个文件，再 exec。管道、重定向正是靠这个窗口搭起来的；若「创建新进程」只有一步，这些都没地方做。</span></p>',6)),(o(),t(n,null,{default:e(()=>[l(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SH%5B%22shell%3A%E8%AF%BB%E5%8F%96%E5%91%BD%E4%BB%A4%20ls%20-l%22%5D%20--%3E%20FK%5B%22%E8%B0%83%E7%94%A8%20fork%22%5D%0A%20%20FK%20--%3E%20PAR%5B%22%E7%88%B6%3A%E8%AE%B0%E5%BD%95%E5%AD%90%20PID%22%5D%0A%20%20FK%20--%3E%20CHI%5B%22%E5%AD%90%3A%E8%BF%94%E5%9B%9E%200%2C%E4%BB%8D%E6%98%AF%20shell%20%E7%9A%84%E5%89%AF%E6%9C%AC%22%5D%0A%20%20CHI%20--%3E%20RED%5B%22%E5%AD%90%E5%85%88%E6%8A%8A%20stdout%20%E9%87%8D%E5%AE%9A%E5%90%91%2F%E6%8E%A5%E5%A5%BD%E7%AE%A1%E9%81%93%22%5D%0A%20%20RED%20--%3E%20EX%5B%22%E8%B0%83%E7%94%A8%20execve%20%E6%8D%A2%E6%88%90%20ls%20%E7%9A%84%E6%98%A0%E5%83%8F%22%5D%0A%20%20EX%20--%3E%20RUN%5B%22ls%20%E8%BF%90%E8%A1%8C%E5%90%8E%E9%80%80%E5%87%BA%22%5D%0A%20%20PAR%20--%3E%20WT%5B%22wait%20%E7%AD%89%E5%AD%90%E7%BB%93%E6%9D%9F%22%5D%0A%20%20RUN%20--%3E%20WT%0A%20%20WT%20--%3E%20PR%5B%22shell%20%E6%89%93%E5%8D%B0%E6%8F%90%E7%A4%BA%E7%AC%A6%2C%E8%AF%BB%E4%B8%8B%E4%B8%80%E6%9D%A1%E5%91%BD%E4%BB%A4%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讨论 <code>vfork</code> 的暂停父进程优化当主路径，不把容器里 PID 映射写完。也不把 fork 炸弹当成习题去构造；资源限制是策略。<code>clone</code> 的细粒度标志是线程课。</p><p>后课默认：子是父的副本，返回值不同。子要换成另一个二进制，下一课讲 <code>execve</code>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>fork 复制 PCB 与地址空间语义；父得 PID，子得 0。</li><li>文件表常共享引用；页的写时复制是后课。</li><li>用新程序覆盖映像是 <code>execve</code>。</li><li>出处：Tanenbaum and Bos, <em>MOS</em>；Ritchie and Thompson, <em>CACM</em> 1974。</li></ul>',5))])}const P=i(c,[["render",p]]);export{_ as __pageData,P as default};
